// Opgeslagen config uit /data lezen en in global context zetten.
// De inlogvelden (behalve wachtwoord) worden voorinvuld. Uitgang 1 = positie herstellen,
// uitgang 2 = apparaten automatisch ophalen (als inloggegevens bekend zijn), uitgang 3 = formulier voorinvullen.
let cfg = {};
try { cfg = JSON.parse(msg.payload); } catch (e) { cfg = {}; }
let posMsg = null;
let fetchMsg = null;
let userMsg = null;
if (cfg && typeof cfg === 'object' && Object.keys(cfg).length) {
    global.set('viessCfg', cfg);
    if (cfg.refreshToken) { global.set('viessRefreshToken', cfg.refreshToken); }
    node.status({ fill: 'green', shape: 'dot', text: 'config geladen' });
    if (cfg.position !== undefined && cfg.position !== null && cfg.position !== '') {
        posMsg = { payload: parseInt(cfg.position, 10) };
    }
    if (cfg.username && cfg.password && cfg.clientId) {
        fetchMsg = {};
    }
    const pre = {};
    if (cfg.username) { pre.username = cfg.username; }
    if (cfg.clientId) { pre.clientId = cfg.clientId; }
    if (Object.keys(pre).length) { userMsg = { payload: pre }; }
}
return [posMsg, fetchMsg, userMsg];

// Inloggegevens opslaan -> global context + bestand, en meteen de apparaten ophalen.
// Uitgang 1 = bestand, uitgang 2 = melding, uitgang 3 = trigger apparaten ophalen.
const p = msg.payload || {};
const prev = global.get('viessCfg') || {};
const cfg = {
    apiBaseUrl: prev.apiBaseUrl || 'https://api.viessmann-climatesolutions.com',
    iamBaseUrl: prev.iamBaseUrl || 'https://iam.viessmann-climatesolutions.com',
    redirectUri: prev.redirectUri || 'vicare://oauth-callback/everest',
    clientId: String(p.clientId || prev.clientId || '').trim(),
    username: String(p.username || '').trim(),
    password: String(p.password || ''),
    deviceKey: prev.deviceKey || '',
    installationId: prev.installationId || '',
    gatewaySerial: prev.gatewaySerial || '',
    deviceId: prev.deviceId || '',
    refreshToken: prev.refreshToken || ''
};
if (prev.position !== undefined) cfg.position = prev.position;
if (prev.feature !== undefined) cfg.feature = prev.feature;
if (!cfg.username || !cfg.password || !cfg.clientId) {
    node.status({ fill: 'red', shape: 'dot', text: 'vul e-mail, wachtwoord en Client ID in' });
    return [null, { payload: 'Vul e-mail, wachtwoord en Client ID in.' }, null];
}
global.set('viessCfg', cfg);
global.set('viessToken', null);
global.set('viessTokenExpiry', 0);
node.status({ fill: 'green', shape: 'dot', text: 'opgeslagen' });
return [
    { payload: JSON.stringify(cfg, null, 2), filename: "/data/viessmann-config.json" },
    { payload: 'Inloggegevens opgeslagen. Apparaten worden opgehaald...' },
    {}
];

// Gekozen apparaat opslaan (global + bestand) + melding. Slaat over als er niets wijzigt.
const key = msg.payload;
if (!key) { return null; }
const cfg = global.get('viessCfg') || {};
if (cfg.deviceKey === key) { return null; }
cfg.deviceKey = key;
const meta = (global.get('viessDeviceMeta') || {})[key];
if (meta) {
    cfg.installationId = meta.installationId;
    cfg.gatewaySerial = meta.gatewaySerial;
    cfg.deviceId = meta.deviceId;
}
global.set('viessCfg', cfg);
const names = global.get('viessDeviceNames') || {};
node.status({ fill: 'green', shape: 'dot', text: 'apparaat ' + (names[key] || key) });
return [
    { payload: JSON.stringify(cfg, null, 2), filename: "/data/viessmann-config.json" },
    { payload: 'Apparaat ingesteld op: ' + (names[key] || key) }
];

// Gekozen positie opslaan (global context + persistent bestand). Uitgang 1 = bestand, 2 = melding.
const val = parseInt(msg.payload, 10);
const cfg = global.get('viessCfg') || {};
cfg.position = isNaN(val) ? 1 : val;
global.set('viessCfg', cfg);
const labels = { 0: 'AC-uit', 1: 'AC-in' };
node.status({ fill: 'green', shape: 'dot', text: 'positie ' + cfg.position });
return [
    { payload: JSON.stringify(cfg, null, 2), filename: "/data/viessmann-config.json" },
    { payload: 'Positie ingesteld op ' + (labels[cfg.position] || cfg.position) + '.' }
];

// Stap 1 van de Viessmann OAuth2-login (Authorization Code + PKCE).
// We genereren een PKCE code_verifier/challenge en sturen een authorize-request met
// HTTP Basic auth (e-mail:wachtwoord). Viessmann antwoordt met een 302-redirect naar
// vicare://oauth-callback/everest?code=... - we volgen die redirect NIET, maar lezen de code.
// Uitgang 1 = authorize-request, uitgang 2 = melding.
const g = global.get('viessCfg') || {};
const clientId = g.clientId || env.get('VIESSMANN_CLIENT_ID') || '';
if (!g.username || !g.password || !clientId) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'geen inloggegevens' });
    return [null, { payload: 'Vul e-mail, wachtwoord en Client ID in en klik Opslaan.' }];
}
const iamBase = g.iamBaseUrl || env.get('VIESSMANN_IAM_URL') || 'https://iam.viessmann-climatesolutions.com';
const redirect = g.redirectUri || 'vicare://oauth-callback/everest';
function b64url(buf) { return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); }
const verifier = b64url(crypto.randomBytes(32));
const challenge = b64url(crypto.createHash('sha256').update(verifier).digest());
flow.set('viessCodeVerifier', verifier);
const params = 'client_id=' + encodeURIComponent(clientId)
    + '&redirect_uri=' + encodeURIComponent(redirect)
    + '&response_type=code'
    + '&code_challenge=' + challenge
    + '&code_challenge_method=S256'
    + '&scope=' + encodeURIComponent('IoT offline_access');
msg.method = 'POST';
msg.url = iamBase + '/idp/v3/authorize?' + params;
msg.headers = {
    'Content-Type': 'application/x-www-form-urlencoded',
    'Authorization': 'Basic ' + Buffer.from(g.username + ':' + g.password).toString('base64')
};
msg.followRedirects = false;
msg.payload = '';
node.status({ fill: 'blue', shape: 'ring', text: 'inloggen...' });
return [msg, null];

// Stap 2: authorization code uit de Location-header halen en inwisselen voor een token.
// Uitgang 1 = token-request, uitgang 2 = foutmelding.
const loc = (msg.headers && (msg.headers.location || msg.headers.Location)) || '';
let code = '';
const m = /[?&]code=([^&]+)/.exec(loc);
if (m) { code = decodeURIComponent(m[1]); }
if (!code) {
    const sc = msg.statusCode || '?';
    node.status({ fill: 'red', shape: 'dot', text: 'login mislukt (' + sc + ')' });
    return [null, { payload: 'Inloggen bij Viessmann mislukt (HTTP ' + sc + '). Controleer e-mail, wachtwoord en Client ID (en dat reCAPTCHA op de client uit staat).' }];
}
const g = global.get('viessCfg') || {};
const clientId = g.clientId || env.get('VIESSMANN_CLIENT_ID') || '';
const iamBase = g.iamBaseUrl || env.get('VIESSMANN_IAM_URL') || 'https://iam.viessmann-climatesolutions.com';
const redirect = g.redirectUri || 'vicare://oauth-callback/everest';
const verifier = flow.get('viessCodeVerifier') || '';
msg.method = 'POST';
msg.url = iamBase + '/idp/v3/token';
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
delete msg.followRedirects;
msg.payload = 'grant_type=authorization_code'
    + '&client_id=' + encodeURIComponent(clientId)
    + '&redirect_uri=' + encodeURIComponent(redirect)
    + '&code_verifier=' + encodeURIComponent(verifier)
    + '&code=' + encodeURIComponent(code);
node.status({ fill: 'blue', shape: 'ring', text: 'token ophalen...' });
return [msg, null];

// Stap 3: token bewaren (incl. refresh_token) en de installaties/apparaten opvragen.
// Uitgang 1 = installaties-request, uitgang 2 = foutmelding.
const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
if (!body.access_token) {
    const sc = msg.statusCode || '?';
    node.status({ fill: 'red', shape: 'dot', text: 'token mislukt (' + sc + ')' });
    return [null, { payload: 'Token ophalen bij Viessmann mislukt (HTTP ' + sc + ').' }];
}
global.set('viessToken', body.access_token);
global.set('viessTokenExpiry', Date.now() + ((Number(body.expires_in) || 3600) * 1000));
const cfg = global.get('viessCfg') || {};
if (body.refresh_token) {
    global.set('viessRefreshToken', body.refresh_token);
    cfg.refreshToken = body.refresh_token;
    global.set('viessCfg', cfg);
}
const apiBase = cfg.apiBaseUrl || env.get('VIESSMANN_API_URL') || 'https://api.viessmann-climatesolutions.com';
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + body.access_token };
msg.url = apiBase + '/iot/v2/equipment/installations?includeGateways=true';
delete msg.payload;
node.status({ fill: 'blue', shape: 'ring', text: 'apparaten ophalen...' });
return [msg, null];

// Vult de apparaat-dropdown en kiest automatisch het actieve apparaat.
// Uitgang 1 = dropdown (opties + selectie), uitgang 2 = melding, uitgang 3 = bestand.
const code = msg.statusCode;
if (code && code !== 200) {
    node.status({ fill: 'red', shape: 'dot', text: 'fout ' + code });
    return [null, { payload: 'Fout bij ophalen apparaten (HTTP ' + code + ').' }, null];
}
const data = (msg.payload && Array.isArray(msg.payload.data)) ? msg.payload.data : [];
const options = [];
const names = {};
const meta = {};
data.forEach(function (inst) {
    const gws = Array.isArray(inst.gateways) ? inst.gateways : [];
    gws.forEach(function (gw) {
        const devs = Array.isArray(gw.devices) ? gw.devices : [];
        devs.forEach(function (dev) {
            const key = inst.id + '|' + gw.serial + '|' + dev.id;
            const desc = dev.modelId || dev.deviceType || ('apparaat ' + dev.id);
            const label = desc + ' (' + gw.serial + ')';
            options.push({ value: key, label: label });
            names[key] = label;
            meta[key] = { installationId: inst.id, gatewaySerial: gw.serial, deviceId: dev.id };
        });
    });
});
global.set('viessDeviceNames', names);
global.set('viessDeviceOptions', options);
global.set('viessDeviceMeta', meta);
const cfg = global.get('viessCfg') || {};
const keys = options.map(function (o) { return o.value; });
let selected = cfg.deviceKey;
if (!selected || keys.indexOf(selected) === -1) {
    selected = options.length ? options[0].value : '';
}
cfg.deviceKey = selected;
if (meta[selected]) {
    cfg.installationId = meta[selected].installationId;
    cfg.gatewaySerial = meta[selected].gatewaySerial;
    cfg.deviceId = meta[selected].deviceId;
}
global.set('viessCfg', cfg);
node.status({ fill: 'green', shape: 'dot', text: options.length + ' apparaat(apparaten)' });
if (!options.length) {
    return [
        { options: [{ value: '', label: '(geen apparaten gevonden)' }], payload: '' },
        { payload: 'Geen apparaten gevonden voor dit account.' },
        null
    ];
}
return [
    { options: options, payload: selected },
    { payload: options.length + ' apparaat(apparaten) gevonden. Actief: ' + (names[selected] || selected) },
    { payload: JSON.stringify(cfg, null, 2), filename: "/data/viessmann-config.json" }
];

// Vult de UI wanneer de pagina wordt geopend (niet alleen bij deploy).
// Uitgang 1 = e-mail/Client ID in formulier, 2 = positie, 3 = apparaat-dropdown (uit cache),
// 4 = apparaten ophalen als er nog geen cache is.
const cfg = global.get('viessCfg') || {};
const pre = {};
if (cfg.username) { pre.username = cfg.username; }
if (cfg.clientId) { pre.clientId = cfg.clientId; }
const userMsg = Object.keys(pre).length ? { payload: pre } : null;
const posVal = (cfg.position !== undefined && cfg.position !== null && cfg.position !== '')
    ? parseInt(cfg.position, 10) : 1;
const posMsg = { payload: posVal };
const opts = global.get('viessDeviceOptions');
let deviceMsg = null;
let fetchMsg = null;
if (opts && opts.length) {
    deviceMsg = { options: opts, payload: cfg.deviceKey || opts[0].value };
} else if (cfg.username && cfg.password && cfg.clientId) {
    fetchMsg = {};
}
return [userMsg, posMsg, deviceMsg, fetchMsg];

// Adaptief pollen. Viessmann-data ververst maar enkele keren per dag en de Basic-API kent
// een dagelijkse limiet, dus de intervallen staan bewust ruim. Snel(ker) als iemand live meekijkt.
const now = Date.now();
const S = 1000;
const iWatch = (parseInt(env.get('VIESSMANN_POLL_WATCHING_SEC'), 10) || 300) * S;
const iActive = (parseInt(env.get('VIESSMANN_POLL_ACTIVE_SEC'), 10) || 900) * S;
const iIdle = (parseInt(env.get('VIESSMANN_POLL_IDLE_SEC'), 10) || 1800) * S;
const watchTimeout = (parseInt(env.get('VIESSMANN_WATCH_TIMEOUT_SEC'), 10) || 90) * S;

const lastAct = flow.get('lastVrmActivity') || 0;
const watching = (now - lastAct) < watchTimeout;
const active = flow.get('viessState') === 'heating';
const interval = watching ? iWatch : (active ? iActive : iIdle);

const lastFetch = flow.get('lastFetchTs') || 0;
if (now - lastFetch >= interval) {
    flow.set('lastFetchTs', now);
    const mode = watching ? 'live' : (active ? 'actief' : 'idle');
    node.status({ fill: 'blue', shape: 'ring', text: 'poll (' + mode + ')' });
    return msg;
}
return null;

// Passieve live-kijk detectie: als de Venus MQTT-broker data stuurt, houdt iemand
// (VRM-app, GX-display of lokale app) de broker 'wakker'. Wij sturen zelf GEEN keepalive,
// dus we ontvangen alleen iets wanneer er daadwerkelijk een live kijker actief is.
flow.set('lastVrmActivity', Date.now());
return null;

// Configuratie uit VRM (global context), met terugval op omgevingsvariabelen.
const g = global.get('viessCfg') || {};
const cfg = {
    apiBaseUrl: g.apiBaseUrl || env.get('VIESSMANN_API_URL') || 'https://api.viessmann-climatesolutions.com',
    iamBaseUrl: g.iamBaseUrl || env.get('VIESSMANN_IAM_URL') || 'https://iam.viessmann-climatesolutions.com',
    clientId: g.clientId || env.get('VIESSMANN_CLIENT_ID') || '',
    installationId: g.installationId || env.get('VIESSMANN_INSTALLATION_ID') || '',
    gatewaySerial: g.gatewaySerial || env.get('VIESSMANN_GATEWAY_SERIAL') || '',
    deviceId: (g.deviceId !== undefined && g.deviceId !== '') ? g.deviceId : (env.get('VIESSMANN_DEVICE_ID') || '0'),
    position: g.position,
    feature: g.feature || env.get('VIESSMANN_CONSUMPTION_FEATURE') || 'heating.power.consumption.total'
};
flow.set('viessCfg', cfg);

if (!cfg.clientId || !cfg.installationId || !cfg.gatewaySerial || cfg.deviceId === '') {
    node.status({ fill: 'yellow', shape: 'ring', text: 'wacht op VRM-configuratie' });
    return null;
}

const token = global.get('viessToken');
const expiry = global.get('viessTokenExpiry') || 0;
if (token && Date.now() < (expiry - 60000)) {
    msg.access_token = token;
    node.status({ fill: 'green', shape: 'dot', text: 'token ok' });
    return [null, msg];
}

const refresh = global.get('viessRefreshToken') || g.refreshToken || '';
if (!refresh) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'log in via VRM-formulier' });
    return null;
}
msg.method = 'POST';
msg.url = cfg.iamBaseUrl + '/idp/v3/token';
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
msg.payload = 'grant_type=refresh_token'
    + '&client_id=' + encodeURIComponent(cfg.clientId)
    + '&refresh_token=' + encodeURIComponent(refresh);
node.status({ fill: 'blue', shape: 'ring', text: 'token vernieuwen...' });
return [msg, null];

const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
if (!body.access_token) {
    const code = msg.statusCode || '?';
    node.status({ fill: 'red', shape: 'dot', text: 'token vernieuwen mislukt (' + code + ')' });
    node.error('Viessmann: token vernieuwen mislukt (HTTP ' + code + '). Log opnieuw in via het VRM-formulier.', msg);
    if (code === 400 || code === 401) { global.set('viessRefreshToken', null); }
    return null;
}
global.set('viessToken', body.access_token);
global.set('viessTokenExpiry', Date.now() + ((Number(body.expires_in) || 3600) * 1000));
if (body.refresh_token) {
    global.set('viessRefreshToken', body.refresh_token);
    const cfg = global.get('viessCfg') || {};
    cfg.refreshToken = body.refresh_token;
    global.set('viessCfg', cfg);
}
msg.access_token = body.access_token;
node.status({ fill: 'green', shape: 'dot', text: 'token vernieuwd' });
return msg;

// Bouwt de read-only feature-aanroep voor het totaalverbruik van de warmtepomp.
const cfg = flow.get('viessCfg') || {};
const token = msg.access_token || global.get('viessToken');
if (!token) { node.error('Geen Viessmann-token beschikbaar.', msg); return null; }
if (!cfg.installationId || !cfg.gatewaySerial) {
    node.status({ fill: 'red', shape: 'dot', text: 'apparaat ontbreekt' });
    return null;
}
const feature = cfg.feature || 'heating.power.consumption.total';
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + token };
msg.url = cfg.apiBaseUrl + '/iot/v2/features/installations/' + encodeURIComponent(cfg.installationId)
    + '/gateways/' + encodeURIComponent(cfg.gatewaySerial)
    + '/devices/' + encodeURIComponent(cfg.deviceId)
    + '/features/' + encodeURIComponent(feature);
delete msg.payload;
return msg;

// Zet het Viessmann verbruiks-feature om naar payload voor een Victron energiemeter (rol: AC load).
// heating.power.consumption.total levert kWh-statistieken (dag/week/maand/jaar). Wij gebruiken:
//  - kWh: cumulatief totaal = som van de 'year'-array (levensduurverbruik, monotoon oplopend).
//  - W: geschat gemiddeld vermogen op basis van de toename van dat totaal tussen twee metingen.
//       (Let op: Viessmann ververst deze data maar enkele keren per dag; W is dus een gemiddelde,
//        geen momentaan vermogen. Zie README.)
const p = msg.payload;
if (!p || typeof p !== 'object') {
    node.status({ fill: 'yellow', shape: 'ring', text: 'geen data ontvangen' });
    return null;
}
const feat = (p.data && p.data.properties) ? p.data : (p.properties ? p : null);
if (!feat || !feat.properties) {
    const em = p.message || p.error || (p.extendedPayload && p.extendedPayload.reason) || '';
    node.status({ fill: 'red', shape: 'dot', text: 'feature niet beschikbaar' });
    node.error('Viessmann feature niet beschikbaar: ' + (em || JSON.stringify(p).slice(0, 160)), msg);
    return null;
}
const props = feat.properties;
const num = function (v) { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
function arr(x) { return (x && Array.isArray(x.value)) ? x.value : []; }
const yearArr = arr(props.year);
const dayArr = arr(props.day);

// Cumulatief levensduurverbruik in kWh = som van alle jaarwaarden.
let cumulative = yearArr.reduce(function (a, b) { return a + num(b); }, 0);
if (!cumulative && dayArr.length) {
    cumulative = dayArr.reduce(function (a, b) { return a + num(b); }, 0);
}

const nowMs = Date.now();
let ef = flow.get('viessEnergyForward');
if (typeof ef !== 'number' || isNaN(ef)) ef = 0;
let lastCum = flow.get('viessLastCumulative');
if (typeof lastCum !== 'number' || isNaN(lastCum)) lastCum = cumulative;
const lastMs = flow.get('viessEnergyTs') || nowMs;

// Monotoon oplopende energieteller (nooit teruglopen).
if (cumulative > ef) ef = cumulative;

// Gemiddeld vermogen schatten uit de toename van het cumulatieve verbruik.
let power = flow.get('viessPower') || 0;
const dCum = cumulative - lastCum;
const dtH = (nowMs - lastMs) / 3600000;
if (dCum > 0 && dtH > 0) {
    power = (dCum * 1000) / dtH;
    flow.set('viessLastCumulative', cumulative);
    flow.set('viessEnergyTs', nowMs);
} else if (dCum <= 0) {
    // Geen nieuw verbruik gerapporteerd; na langere tijd als idle beschouwen.
    const staleH = (nowMs - lastMs) / 3600000;
    if (staleH > 2) power = 0;
}
if (power < 0 || power > 50000) power = 0; // onwaarschijnlijke waarden negeren
flow.set('viessEnergyForward', ef);
flow.set('viessPower', power);

const r = function (v, d) { const f = Math.pow(10, d === undefined ? 0 : d); return Math.round((v || 0) * f) / f; };
const _cfg = flow.get('viessCfg') || {};
let position = (_cfg.position !== undefined && _cfg.position !== null && _cfg.position !== '')
    ? parseInt(_cfg.position, 10)
    : parseInt(env.get('VIESSMANN_METER_POSITION'), 10);
msg.payload = {
    Connected: 1,
    Position: isNaN(position) ? 1 : position,
    'Ac/Power': r(power, 1),
    'Ac/Energy/Forward': r(ef, 3),
    'Ac/L1/Power': r(power, 1),
    'Ac/L1/Energy/Forward': r(ef, 3)
};

const active = power > 50;
flow.set('viessState', active ? 'heating' : 'idle');
node.status({ fill: active ? 'green' : 'blue', shape: 'dot', text: (active ? 'actief ' : 'idle ') + r(power, 0) + ' W | ' + r(ef, 2) + ' kWh' });
return msg;

// Bouwt een statusregel voor het VRM-dashboard.
const p = msg.payload || {};
const w = p['Ac/Power'];
const kwh = p['Ac/Energy/Forward'];
const on = p.Connected ? 'online' : 'offline';
const t = new Date().toLocaleTimeString('nl-NL');
msg.payload = 'Laatste uitlezing: ' + (w != null ? w : '?') + ' W, ' + (kwh != null ? kwh : '?') + ' kWh (' + on + ') @ ' + t;
return msg;

const e = (msg.error && msg.error.message) ? msg.error.message : 'onbekende fout';
msg.payload = 'Fout: ' + e + ' @ ' + new Date().toLocaleTimeString('nl-NL');
return msg;
